@@ -0,0 +1,23 @@
+// Sites: kitchens that share items, suppliers, recipes and dishes but keep
+// their own locations, and so their own batches and stock.
+import { AppError } from "../errors.js";
+
+/** The site used when a request does not name one. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and belongs to the site. */
+export function locationInSite(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && l.site === site);
+}
+
+/** True when the batch is stored in a location of the site (any site when `site` is undefined). */
+export function batchInSite(store, batch, site) {
+  return site === undefined || locationInSite(store, batch.location, site);
+}
