+++ b/tests/sites.test.js
@@ -0,0 +1,60 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+function withAnnexStock() {
+  const ctx = app();
+  const { store } = ctx;
+  store.data.batches.push({ id: 10, itemId: 1, lot: "AX-1", qty: 3, receivedOn: "2026-10-27", expires: "2026-10-30", location: "annex-fridge" });
+  return ctx;
+}
+
+test("the seed has the annex site and its fridge", () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  const loc = store.data.locations.find((l) => l.id === "annex-fridge");
+  assert.deepEqual([loc.site, loc.name, loc.tempC], ["annex", "Annex fridge", 4]);
+  assert.ok(store.data.locations.filter((l) => l.id !== "annex-fridge").every((l) => l.site === "main"));
+});
+
+test("an unknown site is a 400 unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "nope" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("stock on hand, batches and reports see only the request's site", async () => {
+  const { handle } = withAnnexStock();
+  const mainItems = (await handle({ path: "/items" })).body;
+  const annexItems = (await handle({ path: "/items", headers: annex })).body;
+  assert.equal(mainItems.find((i) => i.id === 1).onHand, 10);
+  assert.equal(annexItems.find((i) => i.id === 1).onHand, 3);
+  assert.equal(annexItems.length, mainItems.length);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body.map((b) => b.id), [10]);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 3 * 180);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [10]);
+});
+
+test("cooking uses only the request's site", async () => {
+  const { handle, store } = withAnnexStock();
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  const main = store.data.batches.find((b) => b.id === 10).qty;
+  assert.equal(main, 3);
+});
+
+test("stock-takes are limited to the site's locations", async () => {
+  const { handle } = withAnnexStock();
+  const wrong = await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } });
+  assert.equal(wrong.body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 10, counted: 2 } })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: 10, counted: 2 } });
+  const done = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex });
+  assert.equal(done.body.lines[0].diff, -1);
+});
